function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 1000) return 'grid needs 1 to 1000 rows.';
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 1 || n > 1000) return 'Each row needs 1 to 1000 values.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 0 || v > 9)) return 'Each cell is a digit from 0 to 9.';
  }
  return null;
}

