function minimumOperations(grid) {
  // Try every column colouring with values 0..10 (10 stands for "a value not in the grid").
  const m = grid.length, n = grid[0].length;
  let best = Infinity;
  const chosen = [];
  const search = (j) => {
    if (j === n) {
      let changes = 0;
      for (let i = 0; i < m; i++) for (let c = 0; c < n; c++) if (grid[i][c] !== chosen[c]) changes++;
      best = Math.min(best, changes);
      return;
    }
    for (let v = 0; v <= 10; v++) {
      if (j > 0 && chosen[j - 1] === v) continue;
      chosen.push(v);
      search(j + 1);
      chosen.pop();
    }
  };
  search(0);
  return best;
}

