function generate(rand, size) {
  const rows = size === 'large' ? 40 + Math.floor(rand() * 61) : 1 + Math.floor(rand() * 4);
  const cols = size === 'large' ? 40 + Math.floor(rand() * 61) : 1 + Math.floor(rand() * 4);
  // A small alphabet makes columns share values, so adjacent columns compete for the same digit.
  const alphabet = size === 'large' ? 2 + Math.floor(rand() * 9) : 1 + Math.floor(rand() * 4);
  const loyalty = rand();
  const grid = Array.from({ length: rows }, () => new Array(cols).fill(0));
  for (let c = 0; c < cols; c++) {
    const favourite = Math.floor(rand() * alphabet);
    for (let r = 0; r < rows; r++) grid[r][c] = rand() < loyalty ? favourite : Math.floor(rand() * alphabet);
  }
  return [grid];
}
